// Card generator, ported from the art page (art/directions, round 6). Every card is a 500 x 700 unit drawing; 1 unit = 0.2cqw.
// Layers: enamel base -> under-SVG (patterned band, spandrels) -> art -> over-SVG 1 (gold frame, moldings, corners)
//         -> optional cut-out figure -> over-SVG 2 (cartouche, jewels, plate ornaments) -> HTML text.
// Under 150 px wide the card switches to a compact frame (.small); under 90 px the name banner goes too (cards.css).
// Numbers are printed the way the Python original printed them, so the markup matches the art page byte for byte.
import { ICON_BASE, iconHtml, termsInHtml } from './terms.ts';

export { ICON_BASE };

export type CardKind = 'char' | 'kul' | 'intr' | 'crisis' | 'kader-h' | 'kader-x' | 'hirs' | 'taraf-s' | 'taraf-h';
export type BackKind = 'intr' | 'kader' | 'taraf' | 'hirs' | 'kul' | 'char' | 'crisis';
type Freq = 'once' | 'crisis' | 'always';

export interface CardSpec {
  kind: CardKind;
  name: string;
  med: string;                                                   // corner-gem icon name
  field?: 'harem' | 'divan' | 'saray' | 'ly' | 'tr';
  art?: { src: string; pos?: string };                           // photo in the window (full URL)
  cut?: { src: string; cl: number; cw: number; ct: number; op: string }; // character cut-out, cutplace.json semantics
  backdrop?: 'studio' | 'dusk';                                  // behind a cut-out
  artSvg?: 'hirs' | 'taraf-s' | 'taraf-h' | { emblem: string };  // drawn art when there is no photo
  bodyHtml: string;
  flavor?: string;
  seal?: 'ok' | 'broken';
  stamp?: { text: string; tone: 'used' | 'ok' };                 // a state stamped across the picture (Kul used, Hırs done)
  pal?: 'sultan';
  variant?: string;
}

const BEZEL_L = 'M0 -52A14 14 0 0 1 26 -45A14 14 0 0 1 45 -26A14 14 0 0 1 52 0A14 14 0 0 1 45 26A14 14 0 0 1 26 45A14 14 0 0 1 0 52A14 14 0 0 1 -26 45A14 14 0 0 1 -45 26A14 14 0 0 1 -52 0A14 14 0 0 1 -45 -26A14 14 0 0 1 -26 -45A14 14 0 0 1 0 -52Z';
const SEAL = 'M0 -44A12 12 0 0 1 22 -38.1A12 12 0 0 1 38.1 -22A12 12 0 0 1 44 0A12 12 0 0 1 38.1 22A12 12 0 0 1 22 38.1A12 12 0 0 1 0 44A12 12 0 0 1 -22 38.1A12 12 0 0 1 -38.1 22A12 12 0 0 1 -44 0A12 12 0 0 1 -38.1 -22A12 12 0 0 1 -22 -38.1A12 12 0 0 1 0 -44Z';

const NAME_Y = 380; // name cartouche centre, in card units (of 700)

// ------------------------------------------------------------------ number printing (Python parity)
const fx = (n: number, d: number) => n.toFixed(d);
/** str() of a Python float: integral values keep their ".0". */
const pf = (n: number) => (Number.isInteger(n) ? `${n}.0` : String(n));
const q = (u: number) => `${fx(u * 0.2, 2)}cqw`;

