// ------------------------------------------------------------------ geometry helpers
type Win = (x0: number, x1: number, yt: number, ys: number, yb: number) => string;

const pointed: Win = (x0, x1, yt, ys, yb) => {
  const w = x1 - x0, cx = (x0 + x1) / 2;
  return `M${x0} ${yb}V${ys}C${x0} ${fx(ys - (ys - yt) * .62, 1)} ${fx(cx - w * .3, 1)} ${fx(yt + (ys - yt) * .1, 1)} ${pf(cx)} ${yt}`
    + `C${fx(cx + w * .3, 1)} ${fx(yt + (ys - yt) * .1, 1)} ${x1} ${fx(ys - (ys - yt) * .62, 1)} ${x1} ${ys}V${yb}Z`;
};

const roundarch: Win = (x0, x1, yt, ys, yb) => `M${x0} ${yb}V${ys}A${pf((x1 - x0) / 2)} ${ys - yt} 0 0 1 ${x1} ${ys}V${yb}Z`;

const lobed: Win = (x0, x1, yt, ys, yb) => {
  const w = x1 - x0, a = x0 + w * .2, b = x1 - w * .2;
  return `M${x0} ${yb}V${ys}Q${x0} ${ys - 26} ${x0 + 30} ${ys - 30}A${fx(w * .14, 0)} ${fx(w * .14, 0)} 0 0 1 ${fx(a + 6, 0)} ${fx(yt + 36, 0)}`
    + `A${fx(w * .32, 0)} ${fx((ys - yt) * .9, 0)} 0 0 1 ${fx(b - 6, 0)} ${fx(yt + 36, 0)}A${fx(w * .14, 0)} ${fx(w * .14, 0)} 0 0 1 ${x1 - 30} ${ys - 30}Q${x1} ${ys - 26} ${x1} ${ys}V${yb}Z`;
};

const rectTop: Win = (x0, x1, yt, _ys, yb) => {
  const r = 16;
  return `M${x0} ${yb}V${yt + r}Q${x0} ${yt} ${x0 + r} ${yt}H${x1 - r}Q${x1} ${yt} ${x1} ${yt + r}V${yb}Z`;
};

/** urllib.parse.quote(s, safe=''): encodeURIComponent plus the five characters it leaves alone. */
const pyQuote = (s: string) => encodeURIComponent(s).replace(/[!'()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());

// the window path as a mask, in the art box's own coordinates (viewBox offset), fully percent-encoded
function maskUri(path: string, x0: number, yt: number, w: number, h: number): string {
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' viewBox='${x0} ${yt} ${w} ${h}' preserveAspectRatio='none'><path d='${path}'/></svg>`;
  return 'url(data:image/svg+xml,' + pyQuote(svg) + ')';
}

function cartouche(cy: number, x0 = 26, x1 = 474, h = 64): string {
  const t = cy - h / 2, b = cy + h / 2, m = cy;
  return `M${x0 + 36} ${pf(t)}H${x1 - 36}C${x1 - 22} ${pf(t)} ${x1 - 18} ${pf(t + 12)} ${x1 - 12} ${pf(t + 18)}Q${x1 - 4} ${m - 8} ${x1} ${m}`
    + `Q${x1 - 4} ${m + 8} ${x1 - 12} ${pf(b - 18)}C${x1 - 18} ${pf(b - 12)} ${x1 - 22} ${pf(b)} ${x1 - 36} ${pf(b)}H${x0 + 36}`
    + `C${x0 + 22} ${pf(b)} ${x0 + 18} ${pf(b - 12)} ${x0 + 12} ${pf(b - 18)}Q${x0 + 4} ${m + 8} ${x0} ${m}Q${x0 + 4} ${m - 8} ${x0 + 12} ${pf(t + 18)}C${x0 + 18} ${pf(t + 12)} ${x0 + 22} ${pf(t)} ${x0 + 36} ${pf(t)}Z`;
}

// Kat'ı icon set: -48 for inline 16 px at 3x, -72 for gems, -144 for medallions
const I = (name: string, size: 48 | 72 | 144 = 48) => iconHtml(name, size);
// the same icon placed inside an SVG drawing (card backs, seals)
const IMG = (name: string, x: number | string, y: number | string, w: number) =>
  `<image href="${ICON_BASE}${name}-144.png" x="${x}" y="${y}" width="${w}" height="${w}"/>`;

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#x27;');

