const CART_FILL = { ivory: 'url(#g-ivory)', lapis: 'url(#g-enamel-lapis)', crimson: 'url(#g-enamel-crimson)' };
const FIELD_J = {
  harem: ['harem', 'Alan: Harem'], divan: ['divan', 'Alan: Divan'], saray: ['saray', 'Alan: Saray (Harem ve Divan)'],
  ly: ['loyalty', 'Sadakat yolu'], tr: ['treason', 'İhanet yolu'],
} as const;

// ------------------------------------------------------------------ drawn art
// portrait backdrops behind a cut-out: their own lit space, contrasting with the red velvet frame
const BACKDROP = {
  studio: '<svg class="bd" viewBox="0 0 400 310" preserveAspectRatio="xMidYMid slice" aria-hidden="true">'
    + '<rect width="400" height="310" fill="url(#st-bg)"/><rect width="400" height="310" fill="url(#st-halo)"/><rect width="400" height="310" fill="url(#st-vig)"/></svg>',
  dusk: '<svg class="bd" viewBox="0 0 400 310" preserveAspectRatio="xMidYMid slice" aria-hidden="true">'
    + '<rect width="400" height="310" fill="url(#dusk-bg)"/><rect width="400" height="310" fill="url(#p-zerefsan)" opacity=".9"/>'
    + '<rect width="400" height="310" fill="url(#dusk-halo)"/><rect width="400" height="310" fill="url(#st-vig)"/></svg>',
};

// a gold şemse with an icon, on ebru
function artHirs(icon: string): string {
  const sem = 'M200 50C262 96 292 146 292 196S262 296 200 342C138 296 108 246 108 196S138 96 200 50Z';
  return `<svg viewBox="0 0 400 350" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect x="-40" y="-40" width="480" height="430" fill="url(#g-ebru)" filter="url(#f-ebru)"/>`
    + `<rect width="400" height="350" fill="#2a0c28" opacity=".25"/>`
    + `<g filter="url(#f-shadow)"><path d="${sem}" transform="translate(0 -22)" fill="url(#g-gold)" filter="url(#f-bevel)"/>`
    + `<path d="${sem}" transform="translate(200 174) scale(.84) translate(-200 -196)" fill="url(#j-ivory)"/></g>`
    + IMG(icon, 140, 114, 120) + '</svg>';
}

// Sadık: a teal shield with çintemani; Hain: a dagger
function artTaraf(sadik: boolean): string {
  const SHIELD = 'M200 40L292 74V160C292 234 250 274 200 298C150 274 108 234 108 160V74Z';
  const SHIELD_IN = 'M200 62L272 88V160C272 218 240 250 200 270C160 250 128 218 128 160V88Z';
  const em = sadik
    ? `<g filter="url(#f-shadow)"><path d="${SHIELD}" fill="url(#g-gold)" filter="url(#f-bevel)"/><path d="${SHIELD_IN}" fill="url(#j-teal)"/>`
      + '<g fill="none" stroke="#ffe6a0" stroke-width="7"><circle cx="182" cy="140" r="15"/><circle cx="218" cy="140" r="15"/><circle cx="200" cy="170" r="15"/>'
      + '<path d="M160 208c10-10 20-10 30 0s20 10 30 0s20-10 30 0M160 228c10-10 20-10 30 0s20 10 30 0s20-10 30 0" stroke-width="5"/></g></g>'
    : '<g filter="url(#f-shadow)"><g filter="url(#f-bevel)" fill="url(#g-gold)"><path d="M200 26C228 70 234 142 214 206H186C174 142 174 76 200 26Z"/>'
      + '<path d="M146 206H254L244 226H156Z"/><circle cx="200" cy="304" r="17"/></g><path d="M187 226H213V288H187Z" fill="url(#j-crimson)"/>'
      + '<path d="M200 50C214 86 216 140 206 196" fill="none" stroke="#7a5418" stroke-width="3" opacity=".6"/></g>';
  const bg = sadik ? '#17605f' : '#3a0c10';
  return `<svg viewBox="0 0 400 350" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><rect width="400" height="350" fill="${bg}"/>`
    + `<rect width="400" height="350" fill="url(#p-cintemani)"/><rect width="400" height="350" fill="url(#p-halkari)" opacity=".5"/>${em}</svg>`;
}

function drawnArt(a: CardSpec['artSvg']): string {
  if (!a) return '';
  if (a === 'hirs') return artHirs('ambition');
  if (a === 'taraf-s') return artTaraf(true);
  if (a === 'taraf-h') return artTaraf(false);
  return artHirs(a.emblem);
}

// ------------------------------------------------------------------ text helpers
const FQ: Record<Freq, [string, string]> = { once: ['once', 'Oyunda bir'], crisis: ['percrisis', 'Krizde bir'], always: ['always', 'Her zaman'] };

/** The frequency icon on its bronze disc; the words are the tooltip. */
export function freqHtml(freq: Freq): string {
  const [ic, label] = FQ[freq];
  return `<span class="fq" title="${label}" aria-label="${label}" role="img" data-noterms>${I(ic)}</span>`;
}



/** A body paragraph with term icons (T() in the original). */
export function para(textHtml: string): string {
  return `<p data-terms>${termsInHtml(textHtml)}</p>`;
}

const LOCK = '<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="4.5" y="9" width="11" height="8" rx="1.5"/><path d="M7 9V6.5a3 3 0 016 0V9"/></svg>';

/** The state of a power in play: used powers are faded and labelled, a locked Lütuf power carries a lock. */
export interface PowerMark { state: 'ready' | 'used' | 'locked'; label: string }

/** A Character power: frequency icon, name, text, in one run. Base and Lütuf look alike (the Lütuf power is the lower
 *  one); a mark shows its state in play. */
export function powerHtml(kind: 'base' | 'favor', name: string, freq: Freq | null, textHtml: string, mark?: PowerMark): string {
  const st = mark && mark.state !== 'ready'
    ? `<span class="pw-st ${mark.state}" title="${esc(mark.label)}">${mark.state === 'locked' ? LOCK : esc(mark.label)}</span>` : '';
  const inner = `${freq ? freqHtml(freq) + ' ' : ''}<b class="pn">${name}:</b> ${textHtml}`;
  return `<div class="pw ${kind} ${mark?.state ?? ''}">${st}<p data-terms>${termsInHtml(inner)}</p></div>`;
}

/** The ornament between the two powers: a line, a diamond, a line. */
export const POWER_SEP = '<div class="pw-sep" aria-hidden="true"><i></i></div>';

// ------------------------------------------------------------------ the card
export function cardHtml(s: CardSpec): string {
  const { kind, name, med, field, cut, pal, seal } = s;
  const t = T[pal ?? kind];
  // corner gems: a black disc on light frames (Entrika, Kriz, Süleyman's gold), a white one on dark frames, so the icon
  // stands out; .gem-dk switches their icons to the light tint
  const gemDark = t.light === true || pal === 'sultan';
  const disc = gemDark ? '#17110d' : '#fffdf6';
  // one name line on every card type; windows and plates adapt. Character cards sit it higher: two powers and a flavor
  // line need the taller plate.
  const cy = kind === 'char' ? NAME_Y - 30 : NAME_Y;
  const wx0 = 50, wx1 = 450, wyt = 72;
  const wys = wyt + (t.win !== rectTop ? 80 : 0);
  const winpath = t.win(wx0, wx1, wyt, wys, cy);
  const ah = cy - wyt;
  const mask = maskUri(winpath, wx0, wyt, wx1 - wx0, ah);

  // ---- under: patterned frame band and spandrels
  const band = t.band
    ? `<path class="fine" fill-rule="evenodd" fill="url(#${t.band})" d="M33 15H467Q485 15 485 33V667Q485 685 467 685H33Q15 685 15 667V33Q15 15 33 15Z`
      + 'M37 31H463Q469 31 469 37V663Q469 669 463 669H37Q31 669 31 663V37Q31 31 37 31Z"/>'
    : '<g class="fine" fill="none"><rect x="18" y="18" width="464" height="664" rx="8" stroke="#1f3c86" stroke-width="2"/>' // paper cards: cetvel rules
      + '<rect x="23" y="23" width="454" height="654" rx="6" stroke="#b3311d" stroke-width="1.2"/>'
      + '<rect x="27" y="27" width="446" height="646" rx="5" stroke="#2a7f7a" stroke-width="1"/></g>';
  const span = `<rect class="fine spandrel" x="35" y="35" width="430" height="630" fill="url(#${t.span})"/>`;
  const under = `<svg class="L big under" viewBox="0 0 500 700" aria-hidden="true">${span}${band}</svg>`;

  // ---- art
  const drawn = s.backdrop ? BACKDROP[s.backdrop] : drawnArt(s.artSvg);
  let img: string;
  if (cut) { // the cut-out figure on a uniform backdrop
    img = drawn + `<img class="fig" src="${cut.src}" alt="" decoding="sync" `
      + `style="left:${pf(cut.cl)}%;width:${pf(cut.cw)}%;top:${pf(cut.ct)}cqw;object-position:${cut.op}">`;
  } else if (s.art) {
    img = `<img src="${s.art.src}" alt="" style="object-position:${s.art.pos ?? '50% 30%'}" decoding="sync">`;
  } else {
    img = drawn;
  }
  const artHtml = `<div class="art" style="--ax:${q(wx0)};--ay:${q(wyt)};--aw:${q(wx1 - wx0)};--ah:${q(ah)};--am:${mask}">${img}</div>`;

  // ---- over 1: gold frame, molding, corners
  const frameInner = t.light ? '#5b3b12' : '#120b06';
  const over1 = '<svg class="L big" viewBox="0 0 500 700" aria-hidden="true">'
    + '<g filter="url(#f-bevel)"><rect x="7" y="7" width="486" height="686" rx="18" fill="none" stroke="url(#g-gold)" stroke-width="10"/>'
    + '<rect x="32.5" y="32.5" width="435" height="635" rx="6" fill="none" stroke="url(#g-gold)" stroke-width="3.5"/></g>'
    + `<rect x="14" y="14" width="472" height="672" rx="13" fill="none" stroke="${frameInner}" stroke-width="1.8"/>`
    + `<g class="mold" filter="url(#f-bevel)"><path d="${winpath}" fill="none" stroke="url(#g-gold)" stroke-width="10"/></g>`
    + `<path class="mold" d="${winpath}" fill="none" stroke="#2a1606" stroke-width="1.3" opacity=".8"/>`
    + '<g class="fine" filter="url(#f-bevel)" fill="url(#g-gold)"><use href="#s-corner" x="35" y="585" width="80" height="80"/>'
    + '<use href="#s-corner" x="-465" y="585" width="80" height="80" transform="scale(-1 1)"/></g>'
    + '<g class="fine" opacity=".75"><use href="#s-corner-line" x="35" y="585" width="80" height="80"/><use href="#s-corner-line" x="-465" y="585" width="80" height="80" transform="scale(-1 1)"/></g>'
    + '<path class="fine" filter="url(#f-bevel)" fill="url(#g-gold)" d="M250 662C262 670 266 680 250 696C234 680 238 670 250 662Z"/>'
    + '</svg>';

  // ---- cut-out figure breaking the arch: only the head region, above the arch's spring line
  let cutHtml = '';
  if (cut) {
    const bx0 = wx0 + (wx1 - wx0) * .18, bw = (wx1 - wx0) * .64; // a band 64 % of the window wide
    const il = (cut.cl / 100 * (wx1 - wx0) + wx0 - bx0) * .2;    // image left inside the band, cqw
    const iw = cut.cw / 100 * (wx1 - wx0) * .2;
    cutHtml = `<div class="cut big" style="left:${q(bx0)};width:${q(bw)};height:${q(wys)}">`
      + `<img src="${cut.src}" alt="" decoding="sync" style="left:${fx(il, 2)}cqw;width:${fx(iw, 2)}cqw;top:${fx(wyt * .2 + cut.ct, 2)}cqw"></div>`;
  }

  // ---- over 2: cartouche, jewels, plate ornaments, seal
  const cfill = CART_FILL[t.cart];
  const cpath = cartouche(cy);
  const sealSvg = seal ? `<g filter="url(#f-shadow)">${IMG(seal === 'ok' ? 'hizmet' : 'hiyanet', 196, cy - 106, 108)}</g>` : '';
  // corner medallions: a thin gold rim round a wide contrast disc, so the icon gets the room
  const jewel = (x: number) => `<g transform="translate(${x} 60)" filter="url(#f-shadow)"><circle r="34" fill="url(#g-gold)" filter="url(#f-bevel)"/>`
    + `<circle r="30.5" fill="${disc}"/><circle r="30.5" fill="none" stroke="#3a2208" stroke-width="1"/></g>`;
  const jewels = jewel(60) + (field ? jewel(440) : '');
  const pt = cy + 40;
  const plateOrn = `<g class="fine" fill="url(#g-gold)" filter="url(#f-bevel)"><path d="M44 ${pt}h22l-22 22z"/><path d="M456 ${pt}h-22l22 22z"/>`
    + '<path d="M44 652h22l-22 -22z"/><path d="M456 652h-22l22 -22z"/></g>';
  const alem = ['char', 'kader-h', 'kader-x', 'taraf-s', 'taraf-h', 'hirs'].includes(kind)
    ? `<g class="alem" filter="url(#f-shadow)" transform="translate(250 ${wyt}) scale(1.45)"><g filter="url(#f-bevel)" fill="url(#g-gold)">`
      + '<path d="M0 -34c10 7 15 15 15 23s-7 13-15 13s-15-5-15-13s5-16 15-23z"/>'
      + '<path d="M-26 4C-20 -10 -6 -12 0 -5C6 -12 20 -10 26 4C17 0 7 2 0 9C-7 2 -17 0 -26 4Z"/></g>'
      + `<circle cy="-16" r="5.5" fill="url(#${t.jewel})"/></g>`
    : '';
  const over2 = `<svg class="L big" viewBox="0 0 500 700" aria-hidden="true">${plateOrn}${sealSvg}${alem}`
    + `<g filter="url(#f-shadow)"><path d="${cpath}" fill="${cfill}"/></g>`
    + `<path d="${cpath}" fill="none" stroke="url(#g-gold)" stroke-width="5" filter="url(#f-bevel)"/>`
    + `<path d="${cartouche(cy, 40, 460, 46)}" fill="none" stroke="${t.cart === 'ivory' ? t.accent : '#e3c167'}" stroke-width="1.4" opacity=".75"/>`
    + `${jewels}</svg>`;

  // ---- compact frame (< 150 px)
  const sc = cartouche(612, 16, 484, 92);
  const small = '<svg class="L small" viewBox="0 0 500 700" aria-hidden="true">'
    + (pal === 'sultan'
      ? '<g filter="url(#f-bevel)"><rect x="22" y="22" width="456" height="656" rx="16" fill="none" stroke="url(#g-gold)" stroke-width="30"/></g>'
      : `<rect x="20" y="20" width="460" height="660" rx="16" fill="none" stroke="${t.e1}" stroke-width="14"/>`)
    + '<g filter="url(#f-bevel)"><rect x="9" y="9" width="482" height="682" rx="20" fill="none" stroke="url(#g-gold)" stroke-width="16"/>'
    + '<rect x="28" y="28" width="444" height="644" rx="12" fill="none" stroke="url(#g-gold)" stroke-width="5"/></g>'
    + `<g class="sname"><path d="${sc}" fill="${cfill}" filter="url(#f-shadow)"/><path d="${sc}" fill="none" stroke="url(#g-gold)" stroke-width="7" filter="url(#f-bevel)"/></g>`
    + `<g transform="translate(84 84)" filter="url(#f-shadow)"><path d="${BEZEL_L}" fill="url(#g-gold)" filter="url(#f-bevel)"/><circle r="40" fill="${disc}"/></g>`
    + (field ? `<g transform="translate(416 84)" filter="url(#f-shadow)"><path d="${BEZEL_L}" fill="url(#g-gold)" filter="url(#f-bevel)"/><circle r="40" fill="${disc}"/></g>` : '')
    + '</svg>';

  // ---- HTML text
  let fld = '';
  if (field) {
    const [ic, tip] = FIELD_J[field];
    fld = `<span class="fj" title="${tip}" aria-label="${tip}" role="img">${I(ic, 72)}</span>`;
  }
  const nmCls = [...name].length > 13 ? 'nm long' : 'nm';
  const py = cy + 42, ph = 650 - cy - 42; // every type: the plate starts right under the name and runs to the bottom margin
  const plate = `<div class="plate big" style="--py:${q(py)};--ph:${q(ph)}"><div class="pin">${s.bodyHtml}`
    + (s.flavor ? `<p class="fl">${s.flavor}</p>` : '') + '</div></div>';
  const cls = ['c3', `t-${kind}`, pal, gemDark && 'gem-dk', s.variant].filter(Boolean).join(' ');
  return `<article class="${cls}" style="--e1:${t.e1};--e2:${t.e2};--cy:${q(cy)}" aria-label="${esc(name)}">`
    + `<div class="base"></div>${under}${artHtml}${over1}${cutHtml}${over2}${small}`
    + `<span class="mj">${I(med, 72)}</span>${fld}<h4 class="${nmCls}">${name}</h4>${plate}`
    + (s.stamp ? `<span class="stamp ${s.stamp.tone}">${esc(s.stamp.text)}</span>` : '') + '</article>';
}

// ------------------------------------------------------------------ card backs
export function backHtml(kind: BackKind): string {
  const corner = 'M14 14h44c-6 18-24 34-44 44z';
  const corners = `<g fill="url(#g-gold)" filter="url(#f-bevel)"><path d="${corner}" transform="translate(28 28) scale(2)"/>`
    + `<path d="${corner}" transform="translate(472 28) scale(-2 2)"/><path d="${corner}" transform="translate(28 672) scale(2 -2)"/>`
    + `<path d="${corner}" transform="translate(472 672) scale(-2 -2)"/></g>`;
  const frame = '<g filter="url(#f-bevel)"><rect x="7" y="7" width="486" height="686" rx="18" fill="none" stroke="url(#g-gold)" stroke-width="10"/>'
    + '<rect x="30" y="30" width="440" height="640" rx="6" fill="none" stroke="url(#g-gold)" stroke-width="3"/>'
    + '<rect x="40" y="40" width="420" height="620" rx="4" fill="none" stroke="url(#g-gold)" stroke-width="1.2"/></g>';
  const plate = (y = 588) => `<g class="bplate"><g filter="url(#f-shadow)"><path d="${cartouche(y, 140, 360, 50)}" fill="url(#g-ivory)"/></g>`
    + `<path d="${cartouche(y, 140, 360, 50)}" fill="none" stroke="url(#g-gold)" stroke-width="4" filter="url(#f-bevel)"/></g>`;
  // gold scalloped bezel, enamel ring, ivory disc, the type icon
  const medal = (icon: string, cy = 340, r = 92, ring = 'j-plum', disc = 'j-ivory', iw = 150) =>
    `<g transform="translate(250 ${cy})" filter="url(#f-shadow)"><path d="${BEZEL_L}" transform="scale(${fx(r / 41, 2)})" fill="url(#g-gold)" filter="url(#f-bevel)"/>`
    + `<circle r="${r}" fill="url(#${ring})"/><circle r="${fx(r * .78, 0)}" fill="url(#${disc})"/><circle r="${fx(r * .78, 0)}" fill="none" stroke="#3a2208" stroke-width="2"/></g>`
    + IMG(icon, pf(250 - iw / 2), pf(cy - iw / 2), iw);
  const semse = 'M250 186C318 236 352 292 352 350S318 464 250 514C182 464 148 408 148 350S182 236 250 186Z';
  const pend = 'M250 140c12 8 18 17 18 26s-8 16-18 16s-18-7-18-16s6-18 18-26z';
  const pend2 = 'M250 560c12-8 18-17 18-26s-8-16-18-16s-18 7-18 16s6 18 18 26z';
  let word: string, label: string, body: string;
  switch (kind) {
    case 'intr':
      word = 'ENTRİKA'; label = 'Entrika kart sırtı';
      body = '<rect width="500" height="700" fill="#1f3c86"/><rect width="500" height="700" fill="url(#p-halkari)" opacity=".8"/>'
        + `<g fill="url(#g-gold)" filter="url(#f-bevel)"><path d="${semse}"/><path d="${pend}"/><path d="${pend2}"/></g>`
        + `<path d="${semse}" transform="translate(250 350) scale(.86) translate(-250 -350)" fill="#f3e9cf"/>`
        + `<path d="${semse}" transform="translate(250 350) scale(.86) translate(-250 -350)" fill="url(#p-zerefsan)"/>`
        + IMG('intrigue', 180, 268, 140);
      break;
    case 'kader':
      word = 'KADER'; label = 'Kader kart sırtı';
      body = '<rect width="500" height="700" fill="url(#g-ebru)" filter="url(#f-ebru)"/><rect width="500" height="700" fill="#2a0c10" opacity=".18"/>'
        + `<g transform="translate(250 340)" filter="url(#f-shadow)"><path d="${SEAL}" transform="scale(2.6)" fill="url(#g-gold)" filter="url(#f-bevel)"/>`
        + '<circle r="86" fill="url(#j-crimson)"/><circle r="86" fill="none" stroke="#3a2208" stroke-width="3"/></g>'
        + IMG('kader', 175, 265, 150) + plate();
      break;
    case 'taraf':
      word = 'TARAF'; label = 'Taraf kart sırtı';
      body = '<rect width="500" height="700" fill="#efe2c2"/><rect width="500" height="700" fill="url(#p-zerefsan)"/>'
        + '<path d="M40 40L250 330L460 40M40 660L250 380L460 660" fill="none" stroke="#b39050" stroke-width="2" opacity=".6"/>'
        + '<path d="M40 40L250 330L460 40Z" fill="#e3d3ab" opacity=".55"/>'
        + '<g transform="translate(250 352)" filter="url(#f-shadow)"><path d="M0 -92C40 -96 90 -64 92 -10C96 48 50 92 -4 92C-60 94 -96 46 -92 -6C-88 -60 -44 -88 0 -92Z" fill="url(#j-crimson)"/>'
        + '<circle r="64" fill="url(#j-ivory)"/><circle r="64" fill="none" stroke="#5a0a10" stroke-width="4" opacity=".7"/></g>'
        + IMG('allegiance', 190, 292, 120);
      break;
    case 'hirs':
      word = 'HIRS'; label = 'Hırs kart sırtı';
      body = '<rect width="500" height="700" fill="#4a1f46"/><rect width="500" height="700" fill="url(#p-cintemani)"/>'
        + medal('ambition', 340, 92, 'j-plum') + plate();
      break;
    case 'kul':
      word = 'KUL'; label = 'Kul kart sırtı';
      body = '<defs><radialGradient id="g-kulback" cx=".5" cy=".42" r=".75"><stop offset="0" stop-color="#2f5bb8"/><stop offset=".6" stop-color="#173068"/><stop offset="1" stop-color="#081430"/></radialGradient></defs>'
        + '<rect width="500" height="700" fill="url(#g-kulback)"/><rect width="500" height="700" fill="url(#p-rumi)" opacity=".35"/>'
        + '<rect x="60" y="60" width="380" height="580" rx="190" fill="none" stroke="url(#g-gold)" stroke-width="2" opacity=".7"/>'
        + medal('companion', 340, 92, 'j-cobalt') + plate();
      break;
    case 'char': {
      word = 'KARAKTER'; label = 'Karakter kart sırtı';
      const arch = pointed(160, 340, 200, 290, 470);
      body = '<rect width="500" height="700" fill="#5a1218"/><rect width="500" height="700" fill="url(#p-ogival)"/>'
        + `<g filter="url(#f-shadow)"><path d="${arch}" fill="url(#g-ivory)"/></g>`
        + `<path d="${arch}" fill="none" stroke="url(#g-gold)" stroke-width="10" filter="url(#f-bevel)"/>`
        + IMG('character', 180, 268, 140) + plate();
      break;
    }
    case 'crisis': // Süleyman's tuğra above, the Kriz flame in a medallion below
      word = 'KRİZ'; label = 'Kriz kart sırtı';
      body = '<defs><radialGradient id="g-lacquer" cx=".5" cy=".42" r=".75"><stop offset="0" stop-color="#1d3a33"/><stop offset=".6" stop-color="#0c1f1b"/><stop offset="1" stop-color="#040a09"/></radialGradient></defs>'
        + '<rect width="500" height="700" fill="url(#g-lacquer)"/><rect width="500" height="700" fill="url(#p-halkari)" opacity=".55"/>'
        + '<rect width="500" height="700" fill="url(#p-zerefsan)" opacity=".7"/>'
        + '<use href="#s-tugra" x="56" y="96" width="390" height="240" style="color:#000" opacity=".55"/>'
        + '<use href="#s-tugra" x="52" y="90" width="390" height="240" style="color:#e3c167" filter="url(#f-bevel)"/>'
        + medal('crisis', 438, 64, 'j-crimson', 'j-ivory', 104) + plate();
      break;
  }
  return `<article class="c3 back b-${kind}" role="img" aria-label="${label}"><svg class="L" viewBox="0 0 500 700" aria-hidden="true">${body}${corners}${frame}</svg>`
    + `<div class="bk"><span class="bw">${word}</span></div></article>`;
}
